import { CATALOG, CATEGORIES, STAGES, SEGMENTS, fields, isFileField, categoryFields, formErrors, message, valueByLabel } from './catalog';
import { planDocument } from './documents';
import type { Actor, Appeal, Category, Command, Council, CouncilStatus, Dor, Election, Entity, Implementation, Meeting, Parameters, Registration, Repository, Role, Seat, Segment, Values } from './types';
export const POLICY = 'Demonstração v1: RN006 específica; Bahia; janelas inclusivas; quórum percentual com arredondamento para cima; procurador conta presença, sem voto; prioridade: nomeação/formalização, renovação, vencimento, recondução, inatividade, aditivo, ativo. L03–L23 permanecem não homologadas.';
export class CouncilError extends Error { constructor(public code: string, text: string) { super(text); } }
function fail(text:string,code='DEMO::VALIDACAO'):never {throw new CouncilError(code,text);}
export const official=(dor:Dor,n:number):never=>fail(message(dor,n),`${dor}::MSG${String(n).padStart(3,'0')}`);
export const id=()=>crypto.randomUUID();
export function civil(instant:string){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bahia',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(instant));}
export const instant=(value:string)=>value.length===10?`${value}T00:00:00-03:00`:value.length===16?`${value}:00-03:00`:value;
export function dateOk(value:string){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const dt=new Date(value+'T12:00:00Z');return Number.isFinite(dt.getTime())&&dt.toISOString().slice(0,10)===value;}
export const addDays=(date:string,days:number)=>{const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);};
export const difference=(a:string,b:string)=>Math.round((Date.parse(a+'T12:00:00Z')-Date.parse(b+'T12:00:00Z'))/86400000);
export function mandateEnd(publication:string){if(!dateOk(publication))return fail('Informe uma data de publicação válida.');const [y,m,d]=publication.split('-').map(Number),last=new Date(Date.UTC(y+2,m,0)).getUTCDate();return addDays(`${y+2}-${String(m).padStart(2,'0')}-${String(Math.min(d,last)).padStart(2,'0')}`,-1);}
export function elapsedDays(from:string,to:string,count:'corridos'|'uteis',holidays:string[]=[]){if(!dateOk(from)||!dateOk(to))return NaN;if(count==='corridos')return difference(to,from);let total=0;for(let d=addDays(from,1);d<=to;d=addDays(d,1)){const day=new Date(d+'T12:00:00Z').getUTCDay();if(day!==0&&day!==6&&!holidays.includes(d))total++;}return total;}
export const screenCode=(dor:Dor,num:number)=>`${dor}::TL${String(num).padStart(3,'0')}`;
export function canAccess(actor:Actor,c:Council){if(actor.role==='publico')return true;if(!actor.ucIds.includes(c.uc.id))return false;if(actor.role==='candidato')return !!c.election;if(['conselheiro','secretaria'].includes(actor.role))return c.composition.some(s=>s.active&&s.institutionId===actor.institutionId);return true;}
export function requireRole(actor:Actor,c:Council,roles:Role[]){if(!canAccess(actor,c)||!roles.includes(actor.role))fail('Seu perfil demonstrativo não permite esta ação neste conselho.','DEMO::ACESSO');}
export function councilStatus(c:Council,clock:string):CouncilStatus {
 if(c.election?.appointment&&!c.election.inauguration)return 'Aguardando formalização';
 if(!c.publication)return c.election?.type==='Renovação'?'Renovação em andamento':'Não criado';
 if(!c.posse||!c.implementation?.approvedAt)return c.election&&!c.election.inauguration&&c.election.type==='Renovação'?'Renovação em andamento':'Aguardando formalização';
 if(c.election&&!c.election.inauguration&&c.election.type==='Renovação')return 'Renovação em andamento';
 if(c.expiry<civil(clock))return 'Vencido';
 const i=c.implementation;if(i.reconduction.started&&!i.reconduction.appliedAt)return 'Recondução em andamento';
 const last=i.meetings.filter(m=>m.state==='Realizada').map(m=>m.date).sort().at(-1)||civil(i.approvedAt!);
 if(!c.uc.managerAssigned||difference(civil(clock),last)>i.parameters.inactiveDays)return 'Inativo';
 return c.addenda.length?'Mandato ampliado (aditivo)':'Ativo';
}
export function electionState(e:Election,clock:string){if(e.inauguration)return 'Concluído';if(e.appointment)return 'Aguardando posse';if(e.plenaries.every(p=>p.minute)&&e.plenaries.length===3)return 'Aguardando nomeação';if(!e.publishedAt)return e.signedAt?'Em instrução':'Em planejamento';const n=Date.parse(instant(clock));const stage=e.stages.find(s=>n>=Date.parse(instant(s.start))&&n<=Date.parse(instant(s.end)));return stage?'Em andamento — '+stage.name:'Em andamento — acompanhar cronograma';}
export function validateSchedule(e:Election){if(e.stages.length!==11||e.stages.some((s,i)=>s.id!==String(i+1)))official('DOR0031',4);let previous=-Infinity;for(const s of e.stages){const start=Date.parse(instant(s.start)),end=Date.parse(instant(s.end));if(!Number.isFinite(start)||!Number.isFinite(end)||end<start||start<previous)official('DOR0031',4);previous=end;}if(Date.parse(instant(e.stages[7].end))-Date.parse(instant(e.stages[7].start))!==48*3600000)official('DOR0031',4);}
export function windowOpen(e:Election,stage:number,at:string){const s=e.stages[stage-1],n=Date.parse(instant(at));return !!e.publishedAt&&!!s&&n>=Date.parse(instant(s.start))&&n<=Date.parse(instant(s.end));}
export function defaultParameters():Parameters{return {ordinaryDays:15,extraordinaryDays:5,count:'corridos',first:51,second:33.33,consecutive:3,alternate:5,justifications:2,responseDays:10,replacementDays:7,inactiveDays:90,periodicity:'Bimestral',firstSecretary:'',secondSecretary:'',origin:'Perfil de teste configurável — números ilustrativos, não padrão institucional',holidays:[]};}
export function newElection(c:Council,now:string):Election{return {id:id(),type:c.publication?'Renovação':'Criação',technician:'',observation:'',openedAt:now,state:'Em planejamento',forms:{},entities:[],agenda:[],seats:{'Poder Público':2,'Sociedade Civil Local':2,'Empreendedores Locais':2},stages:STAGES.map((name,i)=>({id:String(i+1),name,start:'',end:'',complete:false})),versions:[],registrations:[],appeals:[],lists:[],plenaries:[],documents:[]};}
export function newImplementation(now:string):Implementation{return {id:id(),openedAt:now,forms:{},parameters:defaultParameters(),calendarYear:Number(civil(now).slice(0,4)),calendarApproval:'',meetings:[],cases:[],activities:[],reconduction:{replies:[],forms:{}},documents:[]};}
export function requiredForm(dor:Dor,section:string,values:Values,category?:Category){const errors=formErrors(dor,section,values,category);if(Object.keys(errors).length)official(dor,1);}
function hasFile(c:Council,file:string,owner?:string){if(!file||!c.attachments.some(a=>a.id===file&&(!owner||a.ownerId===owner)&&a.blob.size===a.size&&a.size>0))fail('Anexe o documento local exigido antes de continuar.');}
function registrationProofs(c:Council,reg:Registration,actor:Actor){for(const section of ['18.5',...(reg.category==='Sociedade Civil Local Não Formalizada'?['18.7']:[])])for(const f of categoryFields('DOR0031',section,reg.category)){if(!isFileField(f))continue;const value=reg.forms[section]?.[f.key];if(value||f.required.startsWith('Sim')||f.required.startsWith('Condicional à categoria:')){try{hasFile(c,value,actor.role==='candidato'?actor.id:undefined);}catch{official('DOR0031',8);}}}}
export function bahiaLocal(value:string){return new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Bahia',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)).replace(' ','T');}
export function displayDate(value:string,time=false){if(!value)return 'Não registrado';if(dateOk(value))return value.split('-').reverse().join('/');const dt=new Date(instant(value));return Number.isFinite(dt.getTime())?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Bahia',dateStyle:'short',...(time?{timeStyle:'short'}:{})}).format(dt):value;}
export function secretaryAssigned(c:Council,actor:Actor){const seat=c.composition.find(s=>s.active&&s.institutionId===actor.institutionId);return !!actor.delegated&&!!seat&&[c.implementation?.parameters.firstSecretary,c.implementation?.parameters.secondSecretary].some(key=>key?.startsWith(seat.id+':'));}
export function automaticRequest(c:Council,dor:Dor):Values {const map:Record<string,string>={'Nome do gestor':c.uc.manager,'Cargo/função do gestor':c.uc.job,'Cargo do gestor':c.uc.job,'Cargo':c.uc.job,'Matrícula do gestor':c.uc.registration,'Matrícula':c.uc.registration,'Lotação do gestor':c.uc.office,'Lotação':c.uc.office,'Nome da UC':c.uc.name,'Grupo da UC':c.uc.group,'Categoria da UC':c.uc.category,'RPGA':c.uc.rpga,'Bacia hidrográfica':c.uc.basin,'Endereço da sede':c.uc.address,'Município da sede':c.uc.municipalities[0],'Telefone da sede':c.uc.phone,'Número do processo':'SEI-DEMO-'+(dor==='DOR0031'?c.election?.id:c.implementation?.id),'Nº do processo':'SEI-DEMO-'+c.implementation?.id,'Nº da portaria de nomeação':c.appointmentNumber,'Número da portaria de nomeação':c.appointmentNumber,'Composição nomeada':c.composition.filter(s=>s.active).map(s=>s.institution+' — '+s.titular+' / '+s.alternate).join('; '),'Data de abertura criação/renovação':civil(c.election?.openedAt||'2026-10-26T15:00:00Z')};const out:Values={};for(const f of fields(dor,'18.1'))if(f.type.includes('Automático')||f.type.includes('automático'))out[f.key]=map[f.label]||(/Anexo/i.test(f.type)?c.attachments.find(a=>a.id==='demo-base')?.id||'':/Telefone|Celular/.test(f.label)?c.uc.phone:/[Ee]-mail/.test(f.label)?c.uc.email:'Referência demonstrativa — fonte institucional não integrada');return out;}
function preserveAutomatic(c:Council,dor:Dor,values:Values){return {...values,...automaticRequest(c,dor)};}
function futureDate(date:string,now:string){if(!dateOk(date)||date>civil(now))fail('Informe uma data válida, sem antecipar um registro de fato já ocorrido.');}
export function frequency(c:Council,seatId:string){const p=c.implementation?.parameters||defaultParameters();let total=0,consecutive=0,justifications=0,present=0;for(const m of (c.implementation?.meetings||[]).filter(m=>m.state==='Realizada'&&(!c.publication||m.date>=c.publication)).sort((a,b)=>a.date.localeCompare(b.date))){const a=m.attendance.find(a=>a.seatId===seatId);if(!a)continue;if(a.titular==='P'||a.alternate==='P'||a.proxy){consecutive=0;present++;continue;}if(a.titular==='N/A'&&a.alternate==='N/A')continue;if((a.titular==='FJ'||a.alternate==='FJ')&&justifications<p.justifications){justifications++;consecutive=0;continue;}total++;consecutive++;}return {present,total,consecutive,justifications,atLimit:total>=p.alternate||consecutive>=p.consecutive};}
