export function shortNotice(c:Council,m:Meeting){const p=c.implementation!.parameters,minimum=m.type==='Ordinária'?p.ordinaryDays:p.extraordinaryDays;return elapsedDays(m.sendPlanned,m.date,p.count,p.holidays)<minimum;}
