export function refreshAlerts(repo:Repository){for(const c of repo.councils){const add=(key:string,text:string,recipients:string[])=>{if(!repo.alerts.some(a=>a.id===key))repo.alerts.push({id:key,councilId:c.id,message:text,at:repo.clock,recipients});};const days=c.expiry?difference(c.expiry,civil(repo.clock)):NaN;if(repo.settings.mandateAlerts.includes(days))add(c.id+'-'+c.expiry+'-'+days,message('DOR0031',12),['Técnico CGEUC','Coordenador CGEUC']);for(const s of c.election?.publishedAt?c.election.stages:[]){for(const edge of ['start','end'] as const)if(difference(s[edge].slice(0,10),civil(repo.clock))===repo.settings.stageLead)add(c.id+'-'+s.id+'-'+s[edge],message('DOR0031',13),['Técnico CGEUC','Gestor UC']);if(!s.complete&&Date.parse(instant(s.end))<Date.parse(repo.clock))add(c.id+'-late-'+s.id+'-'+s.end,'Etapa vencida sem conclusão: '+s.name,['Técnico CGEUC','Gestor UC']);}if(c.election?.appointment&&!c.posse&&difference(addDays(c.election.appointment.published,30),civil(repo.clock))===repo.settings.posseLead)add(c.id+'-posse-'+c.election.appointment.published,message('DOR0031',14),['Técnico CGEUC']);if(councilStatus(c,repo.clock)==='Inativo')add(c.id+'-inactive-'+civil(repo.clock),message('DOR0032',8),['Gestor UC','Coordenador CGEUC']);for(const seat of c.composition.filter(s=>s.active)){if(c.implementation && frequency(c,seat.id).justifications>=c.implementation.parameters.justifications)add(c.id+'-fj-'+seat.id+'-'+c.expiry,message('DOR0032',6),['Técnico CGEUC','Gestor UC']);if(frequency(c,seat.id).atLimit)add(c.id+'-absence-'+seat.id+'-'+c.expiry,message('DOR0032',7),['Técnico CGEUC','Gestor UC']);}}}
